"""Concise Sun-Wu portraits, grounded in the local Three Kingdoms edition."""
from portrait_support import set_portrait


def _life(text, block, quote, note=''):
    return dict(text=text, sourceTitle='《三国志》卷' + str(int(block[1:4])),
                sourceUrl=f'/read/{block[1:4]}/#{block}', quote=quote, note=note)


